   908	            .write_stable,
   909	            .write_alloc,
   910	            => {
   911	                msg.deinit();
   912	                return;
   913	            },
   914	
   915	            else => {},
   916	        }
   917	    }
   918	
   919	    self.io.queueMessage(msg, mutex);
   920	}
